' || tF),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text and recording; no third-party passages, questions or audio copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_LISTENING_06.json 0.1.0", "audio_file": {"file": "BH-TL06-L14F_v1.mp3", "sha256": "6c9f96f11978a10f69917b35371920151ed996204ae76a75fcc26747aeb8682b", "bytes": 5958310, "duration_seconds": 248.232, "contains": "copyright notice, 10 s silence, the whole discussion, without the question cues, 2 s silence", "derived_from": {"file": "IELTS-14-L1_v2.mp3", "sha256": "15e9186ed8f4080904ad034b4554734b07a4705fb7ffdea8eca70a696492719a", "passage_seconds": [52.142, 284.041], "owner_approval": "Owner listening approval of the source recording, 2026-10-27 18:09 Asia/Bishkek"}, "method": "Cut from the approved recording with ffmpeg; no new speech; MP3 192 kbps, 48 kHz mono, copyright metadata", "human_review": "pending: owner listens to this exact file"}}'::jsonb,'8d725cb0322cfa33c5b636d25dd51ce924125ce9dbd7f07fa64a9ffd1b838c96',true) on conflict (code) do nothing;
 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,audio_path,audio_sha256,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-listening-l25-v1','0.1.0','Listening Lesson 14 step 5 of 6: Why did they decide that?','listening','guided_practice','targeted-listening-06/6c9f96f11978a10f69917b35371920151ed996204ae76a75fcc26747aeb8682b/BH-TL06-L14F_v1.mp3','6c9f96f11978a10f69917b35371920151ed996204ae76a75fcc26747aeb8682b','You will hear two students, Amira and Josh, talking to their tutor, Professor Grant, about a presentation. Read LEARN FIRST and the worked example. Then listen to the whole discussion and choose the reason for each decision, A, B or C. You may pause or replay.','Reasons follow ''because'', ''so that'', ''since'' and ''that''s much easier''. A reason someone mentions but does not act on is a trap.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Why will the results go at the start?", "accepted_answers": ["A"], "taxonomy_node_id": "01cbe6ee-f40e-4416-bc41-4c95c67d156a", "supporting_node_id": "610d8325-5a22-4df9-beb0-aa512ff82374", "options": [{"value": "A", "label": "A  The surprising finding is a strong hook."}, {"value": "B", "label": "B  The results took longest to prepare."}, {"value": "C", "label": "C  The background has been removed."}, {"value": "D", "label": "D  The audience asked for them first."}]}, {"id": "q2", "prompt": "Why does the tutor think the background can be so short?", "accepted_answers": ["C"], "taxonomy_node_id": "610d8325-5a22-4df9-beb0-aa512ff82374", "supporting_node_id": "01cbe6ee-f40e-4416-bc41-4c95c67d156a", "options": [{"value": "A", "label": "A  The survey had problems."}, {"value": "B", "label": "B  The history slide covers it."}, {"value": "C", "label": "C  The audience will know the basics."}, {"value": "D", "label": "D  The students have no time."}]}, {"id": "q3", "prompt": "Why should the recommendations include real examples?", "accepted_answers": ["D"], "taxonomy_node_id": "01cbe6ee-f40e-4416-bc41-4c95c67d156a", "supporting_node_id": "610d8325-5a22-4df9-beb0-aa512ff82374", "options": [{"value": "A", "label": "A  The businesses asked for it."}, {"value": "B", "label": "B  They are too short."}, {"value": "C", "label": "C  The tutor wants more slides."}, {"value": "D", "label": "D  They will be more convincing."}]}, {"id": "q4", "prompt": "Why is a bar chart better for how often each group posts?", "accepted_answers": ["C"], "taxonomy_node_id": "610d8325-5a22-4df9-beb0-aa512ff82374", "supporting_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "options": [{"value": "A", "label": "A  Bar charts are easier to make."}, {"value": "B", "label": "B  Pie charts cannot show percentages."}, {"value": "C", "label": "C  The audience needs to compare amounts across groups."}, {"value": "D", "label": "D  There are too many groups for a pie chart."}]}, {"id": "q5", "prompt": "Why does Amira want to include the limitations?", "accepted_answers": ["B"], "taxonomy_node_id": "01cbe6ee-f40e-4416-bc41-4c95c67d156a", "supporting_node_id": "8818c0d5-823d-491f-a73f-b2adda0c4127", "options": [{"value": "A", "label": "A  They are the most surprising finding."}, {"value": "B", "label": "B  Someone in the audience will ask about question four."}, {"value": "C", "label": "C  The tutor insists on it."}, {"value": "D", "label": "D  They make the talk longer."}]}, {"id": "q6", "prompt": "Why does Josh first want to skip the limitations?", "accepted_answers": ["D"], "taxonomy_node_id": "01cbe6ee-f40e-4416-bc41-4c95c67d156a", "supporting_node_id": "44773835-b0ba-4e99-a9a5-c11a0d02bdaf", "options": [{"value": "A", "label": "A  He thinks they are wrong."}, {"value": "B", "label": "B  He did not know about them."}, {"value": "C", "label": "C  The tutor told him to."}, {"value": "D", "label": "D  They are short of time."}]}]'::jsonb,'{"scope": "Targeted IELTS listening exercise; not a full paper or an official IELTS recording.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-listening-targeted-focus-v1", "passage": "LEARN FIRST: decisions have reasons\n\nMany Part 3 questions ask WHY something was decided. Listen for reason words:\n- because, since, so that, as\n- that''s much easier to ..., it would be more convincing ...\n- a reason given as a question: ''Why not open with it?''\nTraps: a reason that is mentioned but does not change the decision (for example, how much work something took).\n\nWORKED EXAMPLE\nYou hear: ''Actually, since the background is now so short, wouldn''t it make more sense for me to do the recommendations as well? I interviewed most of the owners, so I know the examples.''\nWhy does Amira take the recommendations? She knows the examples, and she has time because the background is short.\n\nNow listen and answer six questions.", "focus": "Infer speaker intention and logical relationships: identify the reason behind each decision in a discussion."}'::jsonb || jsonb_build_object('teacher_notes', '1 A, "That''s a strong hook. Why not open with it, rather than burying it in the middle?"
2 C, "I''d cut it to about one minute. The audience will know the basics."
3 D, "They''re sensible, but rather general. Each one would be more convincing with a real example".
4 C, "you''re asking the audience to compare amounts across groups, and that''s much easier to see as bars side by side".
5 B, "they''re the reason question four doesn''t tell us much. If we don''t say so, someone will ask."
6 D, "Honestly, I thought we''d skip them. We''re short of time as it is."
Read each explanation, then listen to that part again and hear the proof yourself.

