' || tF),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text and recording; no third-party passages, questions or audio copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_LISTENING_06.json 0.1.0", "audio_file": {"file": "BH-TL06-L14F_v1.mp3", "sha256": "6c9f96f11978a10f69917b35371920151ed996204ae76a75fcc26747aeb8682b", "bytes": 5958310, "duration_seconds": 248.232, "contains": "copyright notice, 10 s silence, the whole discussion, without the question cues, 2 s silence", "derived_from": {"file": "IELTS-14-L1_v2.mp3", "sha256": "15e9186ed8f4080904ad034b4554734b07a4705fb7ffdea8eca70a696492719a", "passage_seconds": [52.142, 284.041], "owner_approval": "Owner listening approval of the source recording, 2026-10-27 18:09 Asia/Bishkek"}, "method": "Cut from the approved recording with ffmpeg; no new speech; MP3 192 kbps, 48 kHz mono, copyright metadata", "human_review": "pending: owner listens to this exact file"}}'::jsonb,'ce5964e7f483b6876311e2cf53d2545a08622ce45cc215e9a802340c7d84773d',true) on conflict (code) do nothing;
 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,audio_path,audio_sha256,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-listening-l26-v1','0.1.0','Listening Lesson 14 step 6 of 6: Mixed check','listening','independent_check','targeted-listening-06/6c9f96f11978a10f69917b35371920151ed996204ae76a75fcc26747aeb8682b/BH-TL06-L14F_v1.mp3','6c9f96f11978a10f69917b35371920151ed996204ae76a75fcc26747aeb8682b','You will hear two students, Amira and Josh, talking to their tutor, Professor Grant, about a presentation. Read LEARN FIRST and the worked example. Then listen to the whole discussion ONCE, without pausing, and answer six new questions. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Use everything: know who is speaking, wait for the settled answer, choose only confirmed options and listen for the reason.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Who says ''Fair enough'' when the tutor rejects the history slide?", "accepted_answers": ["A"], "taxonomy_node_id": "5e1150ab-ce8c-4037-88cd-0c89cb6632fb", "supporting_node_id": "44773835-b0ba-4e99-a9a5-c11a0d02bdaf", "options": [{"value": "A", "label": "A  Amira"}, {"value": "B", "label": "B  Josh"}, {"value": "C", "label": "C  Professor Grant"}]}, {"id": "q2", "prompt": "Who has heard that the deadline was moved?", "accepted_answers": ["B"], "taxonomy_node_id": "5e1150ab-ce8c-4037-88cd-0c89cb6632fb", "supporting_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "options": [{"value": "A", "label": "A  Amira"}, {"value": "B", "label": "B  Josh"}, {"value": "C", "label": "C  Professor Grant"}]}, {"id": "q3", "prompt": "The smallest businesses have only one or ________ staff", "accepted_answers": ["two", "2"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "1b02bd3d-3b53-4357-ad5b-3e31e3c5f5bd", "answer_format": "text"}, {"id": "q4", "prompt": "What did the students plan to do with the recommendations at first?", "accepted_answers": ["B"], "taxonomy_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "supporting_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "options": [{"value": "A", "label": "A  move them to the start"}, {"value": "B", "label": "B  leave them as they are"}, {"value": "C", "label": "C  remove them"}, {"value": "D", "label": "D  add real examples"}]}, {"id": "q5", "prompt": "According to the tutor, a short limitations slide would show that the students ...", "accepted_answers": ["B"], "taxonomy_node_id": "4bdeaffb-7390-4b00-9955-69b9da537007", "supporting_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "options": [{"value": "A", "label": "A  have collected a lot of data"}, {"value": "B", "label": "B  have thought critically about their own data"}, {"value": "C", "label": "C  need more time"}, {"value": "D", "label": "D  disagree with each other"}]}, {"id": "q6", "prompt": "What does the tutor say about the problems with the survey?", "accepted_answers": ["A"], "taxonomy_node_id": "4bdeaffb-7390-4b00-9955-69b9da537007", "supporting_node_id": "472c05b5-8cc0-43b8-b300-ae5b769d7769", "options": [{"value": "A", "label": "A  They are useful to mention as limitations."}, {"value": "B", "label": "B  They mean the survey cannot be used."}, {"value": "C", "label": "C  They should not be mentioned."}, {"value": "D", "label": "D  They are the students'' most surprising finding."}]}]'::jsonb,'{"scope": "Targeted IELTS listening exercise; not a full paper or an official IELTS recording.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-listening-targeted-focus-v1", "passage": "LEARN FIRST: the whole routine\n\n1. Learn the voices in the first lines (Amira, Josh, Professor Grant).\n2. Read each question and note whether it asks WHO, WHAT was decided or WHY.\n3. Do not choose the first idea: wait for the confirmed answer.\n4. In ''choose TWO'', tick only options that are confirmed for these students.\n\nWORKED EXAMPLE\nQuestion: Who first suggests putting the limitations at the very end?\nYou hear Amira: ''Could they go at the very end, after the recommendations?'' -> Amira\n(The tutor then moves them before the recommendations.)\n\nNow listen once and answer six new questions on your own.", "focus": "Part 3 discussion: speakers, delayed answers, choose TWO and reasons in one check."}'::jsonb || jsonb_build_object('teacher_notes', '1 A, Amira: after "I''d leave it out altogether", Amira answers "Fair enough."
2 B, Josh: "By the way, I heard the deadline had been moved to next Friday." The tutor corrects him.
3 two / 2: "the ones with only one or two staff".
4 B, "We were going to leave them as they are." They then agree to add examples.
5 B, "thirty seconds would show you''ve thought critically about your own data".
6 A, "Those are both useful things to mention when you discuss the limitations."
